s=s.replace("  const modelHost = env.OPEN_METEO_API_KEY ? 'customer-api.open-meteo.com' : 'api.open-meteo.com';\n  const modelAllowed = !!env.OPEN_METEO_API_KEY || env.WEATHER_FUSION_NONCOMMERCIAL === 'true';", "  const direct = createDirectModels({ fetchImpl, now });")
