a=s.index('  async function loadModel(');b=s.index('  async function getForecast(',a)
s=s[:a]+"  async function loadModel(id, location) { return direct.load(id, location); }\n"+s[b:]
s=s.replace("loadModel('hrrr', 'NOAA HRRR · 3 km', 'gfs_hrrr', location)","loadModel('hrrr', location)")
s=s.replace("loadModel('ecmwf', 'ECMWF IFS HRES · 9 km', 'ecmwf_ifs', location)","loadModel('ecmwf', location)")
s=s.replace("loadModel('nbm', 'NOAA National Blend', 'ncep_nbm_conus', location)","loadModel('nbm', location)")
s=s.replace("[id, f.value]", "[id, f.meta.status === 'ready' ? f.value : null]")
s=s.replace('result.modelAccessConfigured = modelAllowed;', "result.modelAccessConfigured = true;\n      result.directModelStatus = result.modelContributions.length === 3 ? 'ready' : 'partial';")
s=s.replace("point.observationStations, HOUR, async (d)", "point.observationStations, 5 * MINUTE, async (d)")
s=s.replace("const stations = (d.features || []).slice(0, 4);", "const distance = (s) => { const c=s.geometry?.coordinates; return c ? (c[1]-location.latitude)**2+((c[0]-location.longitude)*Math.cos(location.latitude*Math.PI/180))**2 : Infinity; };\n          const stations = [...(d.features || [])].sort((a,b)=>distance(a)-distance(b)).slice(0, 6);")
s=s.replace("const facts = { location: data.location,", "const facts = { blendPolicy: data.methodology, modelContributions: data.modelContributions, convectiveGuidance: data.convectiveGuidance, next24HoursPrecipitation: data.precipitation, location: data.location,")
s=s.replace("model: env.WEATHER_FUSION_AI_MODEL || 'gpt-5-mini', store: false, max_output_tokens: 2200,", "model: env.WEATHER_FUSION_AI_MODEL || 'gpt-5-mini', store: false, max_output_tokens: 4000, reasoning: { effort: 'low' },")
s=s.replace('Use only the provided current NWS forecast, local Area Forecast Discussion and model facts. NWS is authoritative; explain uncertainty and timing, do not replace its forecast with a raw model.', 'Use only the supplied blended forecast, official NWS forecast, local Area Forecast Discussion and decoded HRRR, ECMWF and NBM numerical facts. Explain the deterministic Weather Fusion blend; you are not generating new numerical predictions. Compare available model amounts, timing and disagreement. Official NWS warnings are authoritative. Model reflectivity is simulated, not observed radar. A nearby-gridpoint signal is not a prediction for the exact location. Coarse precipitation intervals prorated to hourly resolution cannot establish hourly storm timing.')
s=s.replace('Sources must cite nws and afd, and only those model IDs actually used and available.', 'Sources must cite nws and afd plus each model listed in modelContributions. Discuss the collective guidance and uncertainty, and never claim an unavailable model contributed.')
s=s.replace("if (!Array.isArray(content.sources) || !['nws', 'afd'].every((id) => content.sources.includes(id))", "if (!Array.isArray(content.sources) || !['nws', 'afd', ...data.modelContributions.map(m=>m.id)].every((id) => content.sources.includes(id))")
s=s.replace("      } catch {\n        if (failureCooldown.size", "      } catch (error) {\n        console.warn('Weather Fusion AI synthesis failed:', error?.message || 'unknown error');\n        if (failureCooldown.size")
s=s.replace('return { getForecast, getBriefing, search, radar };', 'return { getForecast, getBriefing, search, radar, modelMaps: direct.maps };')
s=s.replace("app.get('/api/weather-fusion/radar', route(service.radar));", "app.get('/api/weather-fusion/radar', route(service.radar));\n  app.get('/api/weather-fusion/models', route(service.modelMaps));")
